-- Academics mobile sync bridge. Web/server writes publish into the durable mobile stream.
CREATE TABLE IF NOT EXISTS academics_mobile_sync_suppression(record_key TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS academics_mobile_sync_emit(
 id INTEGER PRIMARY KEY AUTOINCREMENT, organization_id TEXT NOT NULL, collection_key TEXT NOT NULL, record_id TEXT NOT NULL,
 operation TEXT NOT NULL CHECK(operation IN ('upsert','delete')), payload_json TEXT, changed_by TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER IF NOT EXISTS academics_mobile_sync_emit_ai AFTER INSERT ON academics_mobile_sync_emit BEGIN
 INSERT INTO mobile_sync_record_versions(organization_id,module_key,collection_key,record_id,version,deleted,server_updated_at,last_device_id)
 VALUES(NEW.organization_id,'academics',NEW.collection_key,NEW.record_id,1,CASE WHEN NEW.operation='delete' THEN 1 ELSE 0 END,CURRENT_TIMESTAMP,NULL)
 ON CONFLICT(organization_id,module_key,collection_key,record_id) DO UPDATE SET version=mobile_sync_record_versions.version+1,deleted=excluded.deleted,server_updated_at=CURRENT_TIMESTAMP,last_device_id=NULL;
 INSERT INTO mobile_sync_tombstones(organization_id,module_key,collection_key,record_id,version,deleted_at,device_id)
 SELECT NEW.organization_id,'academics',NEW.collection_key,NEW.record_id,v.version,CURRENT_TIMESTAMP,NULL FROM mobile_sync_record_versions v
 WHERE NEW.operation='delete' AND v.organization_id=NEW.organization_id AND v.module_key='academics' AND v.collection_key=NEW.collection_key AND v.record_id=NEW.record_id
 ON CONFLICT(organization_id,module_key,collection_key,record_id) DO UPDATE SET version=excluded.version,deleted_at=CURRENT_TIMESTAMP,device_id=NULL;
 DELETE FROM mobile_sync_tombstones WHERE NEW.operation='upsert' AND organization_id=NEW.organization_id AND module_key='academics' AND collection_key=NEW.collection_key AND record_id=NEW.record_id;
 INSERT INTO mobile_sync_changes(organization_id,module_key,collection_key,record_id,version,operation,payload_json,changed_by,device_id,changed_at)
 SELECT NEW.organization_id,'academics',NEW.collection_key,NEW.record_id,v.version,NEW.operation,NEW.payload_json,NEW.changed_by,NULL,CURRENT_TIMESTAMP FROM mobile_sync_record_versions v
 WHERE v.organization_id=NEW.organization_id AND v.module_key='academics' AND v.collection_key=NEW.collection_key AND v.record_id=NEW.record_id;
 DELETE FROM academics_mobile_sync_emit WHERE id=NEW.id;
END;

CREATE TRIGGER IF NOT EXISTS academics_ms_rooms_ai AFTER INSERT ON acad_rooms  BEGIN
 INSERT INTO academics_mobile_sync_emit(organization_id,collection_key,record_id,operation,payload_json,changed_by) VALUES(NEW.organization_id,'scheduling','room:'||NEW.id,'upsert',json_object('entityType','room','id',NEW.id,'campusId',NEW.campus_id,'code',NEW.code,'name',NEW.name,'capacity',NEW.capacity,'roomType',NEW.room_type,'locationText',NEW.location_text,'active',NEW.active,'notes',NEW.notes,'updatedAt',NEW.updated_at),NEW.created_by); END;
CREATE TRIGGER IF NOT EXISTS academics_ms_rooms_au AFTER UPDATE ON acad_rooms  BEGIN
 INSERT INTO academics_mobile_sync_emit(organization_id,collection_key,record_id,operation,payload_json,changed_by) VALUES(NEW.organization_id,'scheduling','room:'||NEW.id,'upsert',json_object('entityType','room','id',NEW.id,'campusId',NEW.campus_id,'code',NEW.code,'name',NEW.name,'capacity',NEW.capacity,'roomType',NEW.room_type,'locationText',NEW.location_text,'active',NEW.active,'notes',NEW.notes,'updatedAt',NEW.updated_at),NEW.created_by); END;
CREATE TRIGGER IF NOT EXISTS academics_ms_rooms_ad AFTER DELETE ON acad_rooms  BEGIN
 INSERT INTO academics_mobile_sync_emit(organization_id,collection_key,record_id,operation,payload_json,changed_by) VALUES(OLD.organization_id,'scheduling','room:'||OLD.id,'delete',NULL,OLD.created_by); END;
